e){font-weight: 700;letter-spacing: -.5px;}\";s:32:\"f513d889cf971b13995cc3fffed2f39b\";s:92:\":root :where(.wp-block-site-title a:where(:not(.wp-element-button))){text-decoration: none;}\";s:32:\"22c37a317cc0ebd50155b5ad78564f37\";s:103:\":root :where(.wp-block-site-title a:where(:not(.wp-element-button)):hover){text-decoration: underline;}\";s:32:\"f2d6868602fe95da6c3ae6daa5b45483\";s:90:\":root :where(.wp-block-term-description){font-size: var(--wp--preset--font-size--medium);}\";s:32:\"1685279bb677da079f4170f16d61615e\";s:84:\":root :where(.wp-block-navigation){font-size: var(--wp--preset--font-size--medium);}\";s:32:\"25289a01850f5a0264ddb79a9a3baf3d\";s:92:\":root :where(.wp-block-navigation a:where(:not(.wp-element-button))){text-decoration: none;}\";s:32:\"026c04da08398d655a95047f1f235d97\";s:103:\":root :where(.wp-block-navigation a:where(:not(.wp-element-button)):hover){text-decoration: underline;}\";s:32:\"e83ceb73c67046422fa48272207a5b8a\";s:52:\":root :where(.wp-block-list li){margin-top: 0.5rem;}\";s:32:\"1b8b5af9cb7796418be3edaf7703509e\";s:0:\"\";s:32:\"cef4ee042e0b7007042b04963f4d208f\";s:0:\"\";s:32:\"1738cc37ebc2f9e59138eb65d9876e13\";s:0:\"\";s:32:\"8ca8b48d1d736d275874a16d2ee6a2df\";s:0:\"\";}}','on'),(129,'recovery_keys','a:0:{}','off'),(137,'_site_transient_timeout_browser_6967ec7261b3cbe6a91d798c6b951c60','1788799193','off'),(138,'_site_transient_browser_6967ec7261b3cbe6a91d798c6b951c60','a:10:{s:4:\"name\";s:6:\"Chrome\";s:7:\"version\";s:9:\"151.0.0.0\";s:8:\"platform\";s:7:\"Windows\";s:10:\"update_url\";s:29:\"https://www.google.com/chrome\";s:7:\"img_src\";s:43:\"http://s.w.org/images/browsers/chrome.png?1\";s:11:\"img_src_ssl\";s:44:\"https://s.w.org/images/browsers/chrome.png?1\";s:15:\"current_version\";s:2:\"18\";s:7:\"upgrade\";b:0;s:8:\"insecure\";b:0;s:6:\"mobile\";b:0;}','off'),(139,'_site_transient_timeout_php_check_986ab27a5c44eb5941b7e3b238532f66','1788799193','off'),(140,'_site_transient_php_check_986ab27a5c44eb5941b7e3b238532f66','a:5:{s:19:\"recommended_version\";s:3:\"8.3\";s:15:\"minimum_version\";s:3:\"7.4\";s:12:\"is_supported\";b:0;s:9:\"is_secure\";b:1;s:13:\"is_acceptable\";b:1;}','off'),(144,'_site_transient_wp_plugin_dependencies_plugin_data','a:1:{s:5:\"tutor\";a:35:{s:4:\"name\";s:54:\"Tutor LMS &#8211; eLearning and online course solution\";s:4:\"slug\";s:5:\"tutor\";s:7:\"version\";s:5:\"4.0.7\";s:6:\"author\";s:61:\"<a href=\"https://profiles.wordpress.org/themeum/\">Themeum</a>\";s:14:\"author_profile\";s:39:\"https://profiles.wordpress.org/themeum/\";s:12:\"contributors\";a:1:{s:7:\"themeum\";a:3:{s:7:\"profile\";s:39:\"https://profiles.wordpress.org/themeum/\";s:6:\"avatar\";s:120:\"https://secure.gravatar.com/avatar/929c471e94b7c131fe4ed9526ae26020dd10097c27c1461c5d3535a4ca467daf?s=96&d=monsterid&r=g\";s:12:\"display_name\";s:7:\"Themeum\";}}s:8:\"requires\";s:3:\"5.3\";s:6:\"tested\";s:5:\"7.0.4\";s:12:\"requires_php\";s:3:\"7.4\";s:16:\"requires_plugins\";a:0:{}s:6:\"rating\";i:88;s:7:\"ratings\";a:5:{i:5;i:481;i:4;i:13;i:3;i:14;i:2;i:19;i:1;i:61;}s:11:\"num_ratings\";i:588;s:11:\"support_url\";s:43:\"https://wordpress.org/support/plugin/tutor/\";s:15:\"support_threads\";i:61;s:24:\"support_threads_resolved\";i:48;s:15:\"active_installs\";i:100000;s:12:\"last_updated\";s:21:\"2026-08-21 1:29am GMT\";s:5:\"added\";s:10:\"2019-02-06\";s:8:\"homepage\";s:20:\"https://tutorlms.com\";s:8:\"sections\";a:5:{s:11:\"description\";s:20091:\"<p>Tutor LMS is a lightweight, feature-packed, and robust WordPress LMS plugin to create and sell courses online easily. All the features of this learning management system hit all the checkpoints for a full-fledged online course marketplace.</p>\n<p>You can create unlimited courses, quizzes, interactive lessons, generate reports, making Tutor LMS the best free WordPress LMS plugin. So, it’s become a breeze to manage educational institutes, online courses, or eLearning websites without writing a single line of code.</p>\n<p>👉 <a href=\"https://tutorlms.com/pricing/\" rel=\"nofollow ugc\">Tutor LMS Pro</a></p>\n<p>👉 <a href=\"https://tutorlms.com/themes/\" rel=\"nofollow ugc\">Tutor LMS Themes</a></p>\n<p>👉 <a href=\"https://demo.tutorlms.io/\" rel=\"nofollow ugc\">Live Demo</a></p>\n<p>👉 <a href=\"https://tutorlms.com/docs/\" rel=\"nofollow ugc\">Documentation</a></p>\n<p>You can also join our <a href=\"https://www.facebook.com/groups/tutorlms\" rel=\"nofollow ugc\">official Facebook Community</a> to know all the latest news and be part of the Tutor LMS.</p>\n<p>Also, check out our Tutor LMS overview video:</p>\n<p><span class=\"embed-youtube\" style=\"text-align:center; display: block;\"><iframe loading=\"lazy\" class=\"youtube-player\" width=\"750\" height=\"422\" src=\"https://www.youtube.com/embed/0TGkkA5J5hE?version=3&#038;rel=1&#038;showsearch=0&#038;showinfo=1&#038;iv_load_policy=1&#038;fs=1&#038;hl=es-VE&#038;autohide=2&#038;wmode=transparent\" allowfullscreen=\"true\" style=\"border:0;\" sandbox=\"allow-scripts allow-same-origin allow-popups allow-presentation allow-popups-to-escape-sandbox\"></iframe></span></p>\n<p>Overall, Tutor LMS is the best WordPress LMS plugin for eLearning enthusiasts. It comes with every core feature you’ll need to build a perfect eLearning website. Additionally, it also has plenty of premium add-ons to empower the core plugin more! A few important addons are Course Builder, Certificate, Social Login, Reports, Content Drip, Assignments, Calendar, etc.</p>\n<p>🔥 <a href=\"https://tutorlms.com/\" rel=\"nofollow ugc\">Get Tutor LMS</a> today and create, customize, manage, and sell online courses efficiently.</p>\n<h3>What People Have to Say:</h3>\n<p>🙆 “This LMS has pretty much everything you’d expect from an LMS and more: Course builder, lessons, several quiz/assignment types, video embed, Zoom integration, front-end dashboard, payment/WooCommerce integrations, and a lot of other great addons. It provides a streamlined experience and is easy to use for both admins, tutors and students. Great support and reasonably priced.” —mariusandersen</p>\n<p>🙆 “I’ve been using WordPress-based LMSs for a few years now and after just a few weeks, this has to be my favorite. Let’s hope that continues.” —terryheick</p>\n<h3>🌟 Top Features</h3>\n<p>Here are the most notable features of Tutor LMS:<br />\n🏗️ Advanced course builder<br />\n🧩 Advanced quiz builder<br />\n🎮 Interactive quiz types<br />\n📱 App-like experience<br />\n🛒 Native eCommerce<br />\n📆 Built-in subscriptions<br />\n🖥️ Tutor LMS AI Studio<br />\n📚 Unlimited courses and lessons<br />\n🎓 Course bundle<br />\n🧒 Kids mode<br />\n🎁 Gift course<br />\n👁️ Course preview<br />\n⏱️ Quiz timer<br />\n📝 Quiz attempts<br />\n🗂️ Content bank<br />\n📊 Individual student &amp; instructor dashboard<br />\n📌 Personalized dashboard for each role (admins, instructors, students)<br />\n📽️ Video lessons<br />\n📹 Multiple video sources (self-hosted, YouTube, Vimeo, embedded video, etc)<br />\n✍️ Note taking for lessons and videos<br />\n📅 Content drip<br />\n📝 Lesson management<br />\n💳 Centralized monetization settings<br />\n🛍️ Guest checkout<br />\n💰 Earning and commission allocation<br />\n💸 Multiple withdrawal options<br />\n📜 Purchase history<br />\n🎨 Course customization<br />\n📊 Course widget<br />\n📝 Instructor registration form<br />\n⭐ Course review and rating system<br />\n💬 Unified Discussions &amp; Q&amp;A<br />\n🎥 Video thumbnail (trailer/teaser)<br />\n🚀 Tracking and resetting course progress<br />\n🌟 Course difficulty level<br />\n⏳ Set course duration<br />\n🌐 Course marketplace<br />\n📋 Add course requirements and instruction<br />\n🔦 Spotlight mode<br />\n🏗️ Page builder support<br />\n🔐 Content security<br />\n📈 Advanced analytics and more<br />\n👥 Manual enrollment<br />\n📊 Creating custom grading scales<br />\n🔔 Automated notifications<br />\n👩‍🏫 Multi-instructor system<br />\n🔐 Social login functionalities<br />\n📧 Email verification<br />\n✉️ Email template editor<br />\n🔒 Tutor LMS REST API authentication support<br />\n🏆 Advanced drag-and-drop certificate builder<br />\n📜 Certificate verification<br />\n👤 Manage active login sessions<br />\n📱 Two-factor authentication<br />\n🛡️ Fraud protection<br />\n🔄 RTL ready<br />\n🌐 Multilingual support<br />\n🔏 GDPR compliance<br />\n🌗 Light/Dark mode<br />\n♿️ Accessibility</p>\n<p>You can learn more about these features from <a href=\"https://tutorlms.com/\" rel=\"nofollow ugc\">our website</a>.</p>\n<h3>Tutor LMS Extended Features</h3>\n<p>Tutor LMS is a perfect solution for anyone who wants to create a full-fledged learning management system. Here are some core uses of Tutor LMS:</p>\n<p>👨‍🎨 <a href=\"https://tutorlms.com/solutions/solo-creators/\" rel=\"nofollow ugc\">Individual Creators</a><br />\n📚 <a href=\"https://tutorlms.com/solutions/schools-and-academies/\" rel=\"nofollow ugc\">Schools &amp; Academies</a><br />\n🏫 <a href=\"https://tutorlms.com/solutions/agencies/\" rel=\"nofollow ugc\">LMS Agencies</a><br />\n💻 <a href=\"https://tutorlms.com/solutions/coaching-businesses/\" rel=\"nofollow ugc\">Coaching Businesses</a><br />\n🎓 <a href=\"https://tutorlms.com/solutions/nonprofits-and-community-builders/\" rel=\"nofollow ugc\">Nonprofits &amp; Communities</a></p>\n<p>These are just a few possibilities! There’s a whole new world of eLearning that’s yet to be discovered using this WordPress LMS plugin.</p>\n<h3>🎨 MODERN AND UNIFORM DESIGN</h3>\n<p>Tutor LMS has the most modern, functional, and uniform user interface for an LMS plugin. The entire interface has been redesigned with perfectionism in mind. It&#8217;s also more accessible now to make things easier for users with disabilities.</p>\n<h3>📒 INTUITIVE COURSE BUILDER</h3>\n<p>With Tutor LMS&#8217;s state-of-the-art <a href=\"https://tutorlms.com/course-builder/\" rel=\"nofollow ugc\">course builder</a>, creating engaging online courses has never been easier. This advanced WordPress LMS plugin empowers you to design unlimited courses with unlimited lessons, quizzes, assignments, videos, and more.</p>\n<p>To focus solely on the course-building process, Tutor LMS also lets you hide headers and footers in the course builder using the spotlight mode. So, whether you&#8217;re a seasoned educator or just starting your online teaching journey, this WordPress LMS plugin equips you with the tools you need to create an interactive learning experiences for your students.</p>\n<h3>🧩 ADVANCED QUIZ BUILDER</h3>\n<p><a href=\"https://tutorlms.com/quizzess/\" rel=\"nofollow ugc\">Create unlimited quizzes</a> with this WordPress course plugin. You can add questions, set the time limit, restrict attempts, set passing grades, etc, right from this WordPress LMS plugin.</p>\n<p>This free LMS plugin supports various quiz types. For example, true/false, multiple choice, single choice, matching, fill-in-the-blanks, and interactive quiz types like draw image, pin image, range, puzzle, and graph.</p>\n<h3>🛒 NATIVE ECOMMERCE</h3>\n<p>Tutor LMS has the most streamlined <a href=\"https://tutorlms.com/ecommerce/\" rel=\"nofollow ugc\">Native eCommerce</a> solution to sell courses directly without relying on third-party plugins. You can offer coupons, manage taxes, manage orders, offer refunds, etc via the Tutor LMS native eCommerce. It also supports both individual and guest checkout and is compatible with popular payment gateways like PayPal, Stripe, Paddle, Mollie, Razorpay, etc.</p>\n<h3>📆 BUILT-IN SUBSCRIPTIONS &amp; MEMBERSHIPS</h3>\n<p>The Tutor LMS built-in <a href=\"https://tutorlms.com/subscriptions/\" rel=\"nofollow ugc\">subscriptions</a> feature offers a complete system for managing recurring payments and membership-based access.</p>\n<p>You can create flexible subscription plans such as monthly, yearly, or custom durations to control how learners access courses. Memberships allow you to group courses or learning content under a single plan, making it easier to offer structured learning access and recurring billing.</p>\n<p>It also supports enrollment fees, seasonal discounts, and certificate access for subscribers, giving you full control over monetization and member experience.</p>\n<h3>🖥️ AI STUDIO</h3>\n<p>Tutor LMS revolutionizes course creation with its cutting-edge <a href=\"https://tutorlms.com/ai/\" rel=\"nofollow ugc\">AI Studio</a>. This innovative tool allows instructors to generate high-quality course content, including course outlines, lessons, quizzes, etc with minimal effort. Simply provide a prompt, and the AI will create structured, engaging content in seconds.</p>\n<h3>🎓 MULTIPLE LEARNING MODES</h3>\n<p>Tutor LMS offers two learning modes to suit different types of learners and teaching needs:</p>\n<ul>\n<li>Modern mode</li>\n<li>Kids mode</li>\n</ul>\n<p>Modern mode provides the default standard LMS experience for general learners and instructors. It is designed for structured online learning and full course functionality.</p>\n<p>Kids mode delivers a playful and more engaging learning environment for younger learners with simplified navigation and a more interactive interface that helps to boost concentration.</p>\n<h3>📚 COURSE BUNDLES</h3>\n<p>With Tutor LMS, you can sell multiple courses in a <a href=\"https://tutorlms.com/course-bundles/\" rel=\"nofollow ugc\">course bundle</a>. Bundles can be offered at a discounted price or structured as a guided learning path by encouraging students to explore complementary topics. This feature enhances course accessibility and creates curated learning journeys tailored to students’ needs. You can also offer certificates for the bundle courses.</p>\n<h3>🗂️ CONTENT BANK</h3>\n<p>Tutor LMS Content Bank lets you create a personal library of reusable lessons, quizzes, and assignments. You can easily organize content in Collections, reuse it across courses, and monitor the usage too. It also lets you import or export collections to share or back up your materials across multiple Tutor LMS websites.</p>\n<h3>🎁 GIFT COURSE</h3>\n<p>The Tutor LMS Gift Course feature allows users to purchase a course and send it to another person as a gift. The recipient receives an email notification with access details to the gifted course.</p>\n<h3>🖥 STUDENT DASHBOARD</h3>\n<p>Each student and instructor registered on your WordPress learning management system will have a frontend dashboard to see their enrolled courses, progress, results, announcements, etc.</p>\n<h3>🧑‍🏫 COURSE MARKETPLACE</h3>\n<p>Tutor LMS is the best LMS plugin to create a course marketplace. You can create unlimited courses and instructors using Tutor LMS. As Admin, you can review instructor profiles, manage earnings, set commission rates, deduct charges, and more. Instructors can also withdraw their earnings conveniently via bank transfer, PayPal, eCheck, etc.</p>\n<h3>📹 MULTIMEDIA ATTACHMENTS</h3>\n<p>Keep your eLearning students engaged using multimedia lessons, H5P interactive lessons, SCORM files, etc. Tutor LMS supports versatile video sources such as Vimeo, YouTube, Bunny Stream, etc.</p>\n<h3>💬 ENGAGE STUDENTS WITH LIVE LESSONS</h3>\n<p>Instructors can conduct live video sessions with students within Tutor LMS and increase interaction with students. They can schedule real-time video meetings using Google Meet, Zoom, Jitsi Meet etc. Simply share the meeting link within the lesson and students can join your live classes. During the live lessons, instructors can use all of the required features to conduct a live class like screen sharing, live Q&amp;A, face-to-face engagement, etc.</p>\n<h3>💬 STUDENT’S Q&amp;A</h3>\n<p>Tutor LMS includes a unified Student’s Q&amp;A section where learners can ask questions and interact with instructors in one organized space.</p>\n<h3>📝 LESSON NOTES</h3>\n<p>Lesson notes allows students to take notes on lessons and videos while learning. Students can access all these notes from their dashboard.</p>\n<h3>✉️ BUILT-IN EMAIL MARKETING &amp; AUTOMATION</h3>\n<p>Tutor LMS supports automatic email notifications for admins, instructors, and students. It is equipped with 50+ email triggers and numerous placeholders. You can use those placeholders to send personalized emails. You can use these <a href=\"https://tutorlms.com/docs/tutor-tutorial-list-of-tutor-lms-email-placeholders/\" rel=\"nofollow ugc\">Tutor LMS email placeholders</a> in both the subject lines and the email body.</p>\n<h3>💵 MULTIPLE COURSE MONETIZATION TOOLS</h3>\n<p>You can monetize your eLearning courses using the <a href=\"https://tutorlms.com/ecommerce/\" rel=\"nofollow ugc\">Tutor LMS native eCommerce</a>. Besides, this WordPress LMS plugin has supports for various monetization plugins such as WooCommerce, Easy Digital Downloads, Paid Memberships Pro, etc. These integrations help you manage course sales, memberships, commissions, and subscriptions efficiently. You can also create coupons, manage taxes, and track revenue with detailed reports and analytics.</p>\n<h3>🏗️ PAGE BUILDER COMPATIBILITY</h3>\n<p>Tutor LMS is a versatile WordPress learning management system plugin that is compatible with popular page builders like <a href=\"https://kirki.com/\" rel=\"nofollow ugc\">Kirki</a>, Elementor, Divi, Oxygen Builder, etc. It also has a dedicated <a href=\"https://wordpress.org/plugins/tutor-lms-elementor-addons/\" rel=\"ugc\">Elementor addons plugin</a>, <a href=\"https://wordpress.org/plugins/tutor-lms-divi-modules/\" rel=\"ugc\">Divi modules</a>, etc.</p>\n<h3>🛡️ CONTENT SECURITY</h3>\n<p>Tutor LMS provides top-notch content security to safeguard your eLearning website. With features like copy protection to prevent unauthorized duplication, hotlink prevention to block external sites from misusing your files, and active login session management, you can easily monitor and control user access.</p>\n<p>Besides, email verification ensures that only legitimate users can enroll in your courses. Additionally, Tutor LMS includes security measures such as honeypot and reCAPTCHA integration to prevent bots and spam, two-factor authentication for enhanced login security, and regular updates to patch any vulnerabilities. All of these robust security features work together to safeguard your content and make it the best WordPress LMS plugin regarding content security.</p>\n<p>It also includes GDPR compliance support to help manage user data responsibly and meet global privacy requirements.</p>\n<h3>🚀 POWERFUL ADDONS</h3>\n<p>This WordPress online course plugin has lots of <a href=\"https://tutorlms.com/addons/\" rel=\"nofollow ugc\">advanced addons</a> to enhance your eLearning platform. A few notable add-ons are Course Bundle, Subscriptions, Content Drip, Certificate, Reports, Social Login, Email, Quiz Export/Import, H5P, Gradebook, Prerequisite, Google Meet, etc.</p>\n<h3>📅 CONTENT DRIP TO SCHEDULE COURSE CONTENT</h3>\n<p>Tutor LMS&#8217;s <a href=\"https://tutorlms.com/content-drip/\" rel=\"nofollow ugc\">Content Drip</a> feature allows you to schedule when your course content will be released. This means you can unlock lessons, quizzes, and other materials based on certain prerequisites or specific future dates. By gradually providing access to new content over time rather than all at once, Content Drip helps keep students engaged and motivated.</p>\n<h3>🧑🏻‍🏫 INSTRUCTOR COLLABORATION</h3>\n<p>With Tutor LMS&#8217;s Multi-Instructor addon, multiple instructors can work together on a single course. They can collaborate to create and manage lectures and quizzes of a single course. Each instructor can track learner progress from their own account.</p>\n<h3>📜 DRAG AND DROP CERTIFICATE BUILDER</h3>\n<p>Tutor LMS offers an advanced drag-and-drop <a href=\"https://tutorlms.com/certificate-builder/\" rel=\"nofollow ugc\">Certificate Builder</a>. You can design a certificate from scratch or use a pre-designed template. It comes with multiple pre-designed templates, plenty of design elements, backdrops, media files, etc. Besides, students can also share their certificates on social media to showcase their educational achievements.</p>\n<p>Certificates also support verification to ensure authenticity and prevent misuse. Anyone can verify the student&#8217;s certificates using the certificate ID. You can also add a QR code on the certificate to make the verification easier.</p>\n<h3>🔗 SINGLE CLICK SOCIAL LOGIN</h3>\n<p>Tutor LMS offers one-click login functionality using the Social Login addon. Students can register and log into your eLearning website using their existing Google, Facebook, and X (formerly Twitter) accounts.</p>\n<h3>📊 INSIGHTFUL REPORTS</h3>\n<p>The Reports addon of Tutor LMS offers comprehensive data on student progress, course performance, analytics, and more. Administrators can access detailed information about Courses, Reviews, Sales, Student data, Earning data, etc right from their LMS platform. These reports provide valuable insights into course effectiveness, helping instructors implement more informed teaching strategies.</p>\n<h3>🌐 MULTILINGUAL SUPPORT</h3>\n<p>Tutor LMS eLearning plugin provides multilingual support using WPML, Weglot, Loco Translate, TranslatePress, etc. Multilingual courses allow students to access courses in their preferred language.</p>\n<h3>🛡️ GDPR COMPLIANCE</h3>\n<p>Tutor LMS includes built-in GDPR compliance support to help manage user data responsibly. It allows administrators to handle personal data with transparency and meet privacy requirements across different regions. Tutor LMS also maintains a complete record of when and which students have accepted the legal terms. You can easily track compliance activity in your dashboard and export consent logs as CSV files whenever needed.</p>\n<h3>♿️ ACCESSIBILITY</h3>\n<p>Tutor LMS is designed with improved accessibility in mind to support a wider range of learners. It enhances usability across the interface, making navigation and course interaction easier for users with different abilities and learning needs.</p>\n<h3>🎨 TUTOR LMS THEMES</h3>\n<p>Tutor LMS offers fast modern, lightweight themes like <a href=\"https://tutorlms.com/themes/pathwise/\" rel=\"nofollow ugc\">Pathwise</a>, <a href=\"https://tutorlms.com/themes/wellthrive/\" rel=\"nofollow ugc\">WellThrive</a>, etc. So, you can create responsive, professional courses and customize them with <a href=\"https://kirki.com/\" rel=\"nofollow ugc\">Kirki</a>. See all available themes on the <a href=\"https://tutorlms.com/themes/\" rel=\"nofollow ugc\">Tutor LMS themes</a> page.</p>\n<h3>🔄 MIGRATION FROM OTHER LMS</h3>\n<p>Tutor LMS provides a seamless <a href=\"https://wordpress.org/plugins/tutor-lms-migration-tool/\" rel=\"ugc\">migration tool</a> to migrate courses from LearnDash, LearnPress, and Lifter LMS. You can effortlessly transfer all course data, sales data, student data, and relevant information to Tutor LMS for a smooth transition.</p>\n<h3>Other Notable Features</h3>\n<p>Here are a few other notable features of this free WordPress LMS plugin.</p>\n<ul>\n<li>\n<p>Google Classroom integration</p>\n</li>\n<li>\n<p>Zoom integration</p>\n</li>\n<li>\n<p>Quiz Export/Import</p>\n</li>\n<li>\n<p>Course Preview</p>\n</li>\n<li>\n<p>Course Attachments</p>\n</li>\n<li>\n<p>Notifications</p>\n</li>\n<li>\n<p>Calendar</p>\n</li>\n<li>\n<p>BuddyPress support</p>\n</li>\n<li>\n<p>H5P integration</p>\n</li>\n</ul>\n<p>All of these Tutor LMS features allow the users to design a more powerful and diverse learning management system.</p>\n\";s:3:\"faq\";s:1567:\"\n<dt id=\"is%20tutor%20lms%20free%3F\">\nIs Tutor LMS free?\n</h4>\n<p>\n<p>Yes, Tutor LMS is available for free with a wide range of features to help you create and manage courses. For access to additional advanced features, you can upgrade to the Pro version.</p>\n</p>\n<dt id=\"how%20do%20i%20sell%20courses%20with%20tutor%20lms%3F\">\nHow do I sell courses with Tutor LMS?\n</h4>\n<p>\n<p>Tutor LMS comes with a Native eCommerce system that&#8217;ll allow you to sell your courses directly on your WordPress site. You can also manage payments, discounts, and taxes within the platform.</p>\n</p>\n<dt id=\"can%20i%20create%20quizzes%20with%20tutor%20lms%3F\">\nCan I create quizzes with Tutor LMS?\n</h4>\n<p>\n<p>Yes, Tutor LMS offers an advanced quiz builder that allows you to create a variety of quiz types including multiple-choice, true/false, matching, and more. You can also set time limits, restrict attempts, and define passing grades.</p>\n</p>\n<dt id=\"can%20i%20use%20tutor%20lms%20for%20membership%20sites%3F\">\nCan I use Tutor LMS for membership sites?\n</h4>\n<p>\n<p>Yes, Tutor LMS has a built-in subscription feature which will allow you to create membership-based eLearning platforms.</p>\n</p>\n<dt id=\"can%20i%20offer%20certifications%20with%20tutor%20lms%3F\">\nCan I offer certifications with Tutor LMS?\n</h4>\n<p>\n<p>Tutor LMS allows you to offer certificates to your students upon course completion. You can create and customize the certificate design and include student information, course details, and your branding using the Tutor LMS Certificate Builder.</p>\n</p>\n\n\";s:9:\"changelog\";s:19382:\"<p>= 4.0.7 &#8211; 20 Aug, 2026</p>\n<p>Fix: Resolved an issue that caused errors when editing courses with the Multi Instructor addon enabled. (Pro)</p>\n<p>= 4.0.6 &#8211; 18 Aug, 2026</p>\n<p>Update: Improved WPML compatibility. (Pro)<br />\nFix: Resolved an issue where the course content author ID was not updated when the course author was changed with the Multi-Instructor add-on enabled. (Pro)<br />\nFix: Patched a security vulnerability related to the course list query parameter.</p>\n<p>= 4.0.5 &#8211; 12 Aug, 2026</p>\n<p>Update: Added an option to return to the homepage from the student dashboard on mobile devices.<br />\nUpdate: Strengthened instructor capability checks for better security.<br />\nUpdate: Changing a course author now updates authorship across all content.<br />\nUpdate: Hid course products from the shop page settings when using Native Monetization.<br />\nFix: Resolved the PHP fatal error caused by WooCommerce Subscriptions renewal orders. (Pro)<br />\nFix: Fixed the incorrect date issue on the enrollment time extension date picker. (Pro)<br />\nFix: Resolved the manual email delivery issue. (Pro)<br />\nFix: Fixed the incorrect URL issue in OTP verification emails. (Pro)<br />\nFix: Resolved the course bundle enrollment limit issue. (Pro)<br />\nFix: Fixed the issue where canceling a failed order removed course access.<br />\nFix: Resolved the issue preventing co-authors from viewing submitted assignments. (Pro)<br />\nFix: Fixed the YouTube preview issue in quiz answer explanations.<br />\nFix: Resolved the display limitation that capped the cart and checkout page at 10 products.<br />\nFix: Fixed the incorrect enrollment date issue on course records. (Pro)<br />\nFix: Resolved the LaTeX equations rendering issue in quiz options.</p>\n<p>= 4.0.4 &#8211; 31 July, 2026</p>\n<p>Fix: Resolved the dark theme compatibility issue in the Course Builder.<br />\nFix: Added translation support for some previously untranslatable strings.<br />\nFix: Fixed the incorrect update notification in Tutor LMS Pro. (Pro)<br />\nFix: Prevented certificates from appearing for courses with no assigned certificate. (Pro)</p>\n<p>= 4.0.3 &#8211; 24 July, 2026</p>\n<p>Fix: Resolved an issue where quiz submissions failed in Legacy Mode.<br />\nFix: Resolved an issue where the correct answer was incorrectly marked in True/False quizzes.<br />\nFix: Resolved an issue where the certificate footer displayed «Tutor LMS» instead of the site title. (Pro)</p>\n<p>= 4.0.2 &#8211; 22 July, 2026</p>\n<p>Update: Add Hyperlink Support to Instructor Feedback and Instructor Notes<br />\nUpdate: Add support for Vimeo unlisted/private video URLs<br />\nUpdate: UX updated for the ordering quiz<br />\nUpdate: Show Full Lesson Name Without Ellipsis in the learning area</p>\n<p>Fix: Forgot Password Redirection Mail (Pro)<br />\nFix: Course deletion issue from the wp admin dashboard<br />\nFix: Unable to Access Locked Lessons from the Sidebar (Pro)<br />\nFix: Users Can Progress Despite Failing a Quiz in Sequential Mode<br />\nFix: Ordering Quiz Questions Reveals Correct Answer Through Predefined Numbering (Pro)<br />\nFix: In RTL mode, the Complete course button icon reverts along with the content &#8211; UI Issue<br />\nFix: Admin can not manually enrolled a student when they already have expired enrollment record. (Pro)<br />\nFix: Manual Payment Gateway Description Disappears When Underline Formatting Is Applied.<br />\nFix: Tutor LMS Native Invoice issue with Elementor.(Pro)<br />\nFix: Fixed an issue where license need to reconnect to get product updates. (Pro)<br />\nFix: Facebook Social Media login does not work.(Pro)<br />\nFix: Quiz Responsive issue.</p>\n<p>= 4.0.1 &#8211; 10 July, 2026</p>\n<p>Update: Enhanced course access security through REST APIs.<br />\nFix: Resolved the lesson video loading issue.<br />\nFix: Resolved an issue preventing learners from starting quizzes.<br />\nFix: Added the missing Quiz Details button on mobile devices.<br />\nFix: Resolved the PHP error triggered by 100% discount coupons.<br />\nFix: Restricted certificate downloads when no certificate template is selected. (Pro)</p>\n<p>= 4.0.0 &#8211; 08 July, 2026</p>\n<p>New: Fully redesigned student learning experience<br />\nNew: App-like mobile experience with thumb-friendly navigation<br />\nNew: 5 new quiz types: Draw Image, Pin Image, Graph, Puzzle, and Range (Pro)<br />\nNew: Kids Mode with a playful, colorful interface<br />\nNew: Light/Dark mode with improved accessibility contrast<br />\nNew: Accessibility support added for users with visual impairments<br />\nNew: Added GDPR compliance support for improved data handling<br />\nNew: Student Dashboard showing live lessons, progress, and tasks at a glance<br />\nNew: Instructor Dashboard with earnings overview, course stats, and student activity<br />\nNew: Switch between instructor and student views right from the dashboard<br />\nNew: New Live Lesson Hub (Pro)<br />\nNew: New Course Calendar with milestones and visual roadmap (Pro)<br />\nNew: Unified discussion and Q&amp;A experience across courses<br />\nNew: Centralized notes across all lessons and videos<br />\nNew: Certificates linked to progress, with dynamic unlocking (Pro)<br />\nNew: Certificate verification feature (Pro)<br />\nNew: Resource Center for PDFs and downloadable assets<br />\nNew: Redesigned quiz interface with detailed tracking and review options<br />\nNew: Question preview added to the Quiz Builder<br />\nNew: AI Studio can now generate quiz questions independently<br />\nNew: Course bundle expiry functionality (Pro)<br />\nNew: Clearer analytics for engagement, progress, and course performance (Pro)<br />\nNew: Centralized course billing with subscriptions, history, and renewals<br />\nNew: Profile management with certificate signature and personal info updates<br />\nNew: Preferences for lesson autoplay, downloads, themes, and accessibility settings<br />\nNew: Micro-interactions with animations and sound effects<br />\nNew: New global design modes — Modern, Kids, and Legacy layouts<br />\nNew: Order history list added for PMPro monetization (Pro)</p>\n<p>Update: Design compatibility improvements for the TutorStarter theme<br />\nUpdate: Full compatibility with the Twenty Twenty-Five theme<br />\nUpdate: Improved H5P support in the student learning area<br />\nUpdate: WPML compatibility updates (Pro)<br />\nUpdate: Better compatibility with Yoast SEO and Rank Math SEO<br />\nUpdate: Gradebook is now shown in the Learning Area (Pro)<br />\nUpdate: Improved translation compatibility<br />\nUpdate: Lesson Note enable/disable option added to admin settings<br />\nUpdate: Improved overall assignment functionality, with further UI refinements (Pro)<br />\nUpdate: Improved Instructor Quiz Attempts preview for better usability<br />\nUpdate: Subscription expiry date is now shown for WooCommerce Subscription enrollments (Pro)<br />\nUpdate: Content Bank now supports all new quiz question types (Pro)<br />\nUpdate: Improved notification list navigation (Pro)<br />\nUpdate: Improved Live Class section on the homepage<br />\nUpdate: Enhanced theme compatibility across Tutor LMS pages and layouts<br />\nUpdate: Improved dashboard and learning area consistency with system default themes<br />\nUpdate: Enhanced login experience and social login modal UI</p>\n<p>= 3.9.15 &#8211; Jul 06, 2026</p>\n<p>Update: Enhanced security for REST API requests.</p>\n<p>= 3.9.14 &#8211; Jun 29, 2026</p>\n<p>Update: Improved compatibility with the block-based WooCommerce checkout page.<br />\nFix: Added validation to ensure withdrawal amounts do not exceed the available payout balance. (Pro)</p>\n<p>= 3.9.13 &#8211; Jun 17, 2026</p>\n<p>Update: Patched multiple security vulnerabilities.</p>\n<p>= 3.9.12 &#8211; Jun 09, 2026</p>\n<p>Update: Added compatibility support for PHP 8.5<br />\nUpdate: Added compatibility support for WordPress 7.0<br />\nUpdate: Patched multiple security vulnerabilities.</p>\n<p>= 3.9.11 &#8211; May 20, 2026</p>\n<p>Update: Improved compatibility with Tutor LMS themes.</p>\n<p>= 3.9.10 &#8211; Apr 29, 2026</p>\n<p>Update: Improved user permission checks to enhance security.<br />\nFix: Resolved an issue where line breaks were not preserved in question–answer text created via the API. (Pro)</p>\n<p>= 3.9.9 &#8211; Apr 13, 2026</p>\n<p>Update: Updated Tutor LMS modals and icons for better WCAG 2 accessibility support.<br />\nUpdate: Added a terms and conditions agreement checkbox to the signup page.<br />\nUpdate: Strengthened security for the eCommerce checkout process.<br />\nFix: Resolved an SQL injection vulnerability on the instructor listing page.<br />\nFix: Resolved Stripe pending status issue for delayed payments. (Pro)</p>\n<p>= 3.9.8 &#8211; Apr 01, 2026</p>\n<p>Update: Added proper authorization check while updating the lessons.<br />\nUpdate: Strengthen SQL queries across multiple deletion and update operations.<br />\nUpdate: Improved security in quiz attempts search by preventing SQL injection.<br />\nFix: Fixed private course enrollment via AJAX without proper validation.<br />\nFix: Resolved the billing profile overwrite issue in Tutor LMS native eCommerce.<br />\nFix: Replaced wp_remote_get with wp_safe_remote_get for safer course import with media files.</p>\n<p>= 3.9.7 &#8211; Feb 25, 2026</p>\n<p>Fix: Resolved SQL injection security vulnerabilities to enhance system security.<br />\nFix: Fixed an issue where Stripe orders were automatically canceled in certain cases.</p>\n<p>= 3.9.6 &#8211; Jan 28, 2026</p>\n<p>Update: Removed the autoload option from ‘email_template_data’ to improve site load performance. (Pro)<br />\nFix: Course content edited with Divi can now be reverted to its original content from the Tutor Course Builder.<br />\nFix: Improved user email verification by validating the token during Google login. (Pro)<br />\nFix: Enhanced the security of email verification link generation. (Pro)<br />\nFix: Added a capability check to the coupon details AJAX request.<br />\nFix: Restricted instructors from deleting courses created by other admins or instructors. (Pro)<br />\nFix: Improved WPML compatibility. (Pro)</p>\n<p>= 3.9.5 &#8211; Jan 08, 2025</p>\n<p>New: Added a certificate download button for Admins and Instructors. (Pro)<br />\nUpdate: Added support for PHP 8.4<br />\nUpdate: Instructors can remove co-instructors from their own courses. (Pro)<br />\nUpdate: Multiple improvements and fixes to gift course functionality. (Pro)<br />\nFix: Fixed security issues.<br />\nFix: Users can now retry payment after a failed transaction. (Pro)<br />\nFix: Filters no longer stop working when the category filter is disabled on the course list page.<br />\nFix: Fixed datepicker style conflict with WooCommerce coupon date picker UI.<br />\nFix: Unpublished rating count no longer appears on the course details page.<br />\nFix: Added some missing cities of Spain to the checkout page dropdown.<br />\nFix: Gift course messages now support special characters. (Pro)</p>\n<p>= 3.9.4 &#8211; Dec 18, 2025</p>\n<p>Update: Compatibility with WordPress 6.9<br />\nFix: Security vulnerabilities</p>\n<p>= 3.9.3 &#8211; Nov 27, 2025</p>\n<p>Fix: Grades were auto-generated for all quizzes after a student attempted any quiz. (Pro)<br />\nFix: Automatic enrollment was not working when users enrolled in cancelled courses.<br />\nFix: Incorrect list of instructors shown when using the Instructor shortcode.<br />\nFix: Certificate download option appearing for courses that don’t provide certificates. (Pro)<br />\nFix: Incorrect email content in the assignment evaluation trigger. (Pro)</p>\n<p>= 3.9.2 &#8211; Nov 10, 2025</p>\n<p>New: Added payment option support for manual enrolment for native monetization. (Pro)<br />\nUpdate: Enhanced Strict Mode — course completion is now blocked if any assignment is failed. (Pro)<br />\nFix: Resolved conflict between Limit Active Login Sessions and WooCommerce Guest Checkout. (Pro)<br />\nFix: Fixed video player issue on mobile devices.<br />\nFix: Corrected issue where course completion emails were sent to the wrong user. (Pro)<br />\nFix: Fixed PHP error on sites that have never used WooCommerce for monetization.<br />\nFix: Resolved issue showing raw HTML code in WooCommerce manual enrolment. (Pro)<br />\nFix: Corrected display issue where courses with multiple purchase options showed Add to Cart instead of View Details. (Pro)<br />\nFix: Fixed quiz import issue. (Pro)<br />\nFix: Resolved the WPML 404 redirection issue in certain scenarios. (Pro)</p>\n<p>= 3.9.1 &#8211; Oct 23, 2025</p>\n<p>Fix: Resolved BunnyNet video not loading issue.<br />\nFix: Resolved Quiz attempt access denied issue.<br />\nFix: Resolved Assignment search is not working. (Pro)</p>\n<p>= 3.9.0 &#8211; Oct 22, 2025</p>\n<p>New: Introducing Lesson &amp; Video Note-Taking. (Pro)<br />\nNew: Certificate Support for Course Bundles. (Pro)<br />\nNew: Allow Admins and Instructors to reset course progress for individual students. (Pro)<br />\nFix: Popover RTL issue.<br />\nFix: Assignment details not showing on start/update assignment page. (Pro)<br />\nFix: Dropdown issue on frontend scheduled courses fixed.<br />\nFix: Warning displayed after student attempts imported quiz.<br />\nFix: Security issues are fixed.</p>\n<p>= 3.8.3 &#8211; Sep 30, 2025</p>\n<p>Update: Improved Tutor LMS x Droip integration for better compatibility and performance.<br />\nFix: PHP fatal error on the WooCommerce email preview screen.</p>\n<p>= 3.8.2 &#8211; Sep 25, 2025</p>\n<p>New: Introduced the assignment resubmission functionality. (Pro)<br />\nNew: Added an option to disable the course Wishlist feature.<br />\nNew: Introduced Phase 2 of Tutor LMS x Droip integration.<br />\nUpdate: Enabled students and instructors to update their email addresses from frontend profile settings. (Pro)<br />\nFix: Resolved the incorrect email being sent on WooCommerce subscription renewal. (Pro)<br />\nFix: Course bundle product defaulting to physical instead of virtual in WooCommerce. (Pro)<br />\nFix: Resolved the LaTeX equation rendering issue.<br />\nFix: Corrected quiz total marks calculation based on final grade.<br />\nFix: Fixed backslash appearing in the certificate’s authorized name. (Pro)<br />\nFix: Hid the gift course button for WooCommerce subscriptions. (Pro)</p>\n<p>= 3.8.1 &#8211; Sep 17, 2025</p>\n<p>Update: Admins can now export courses with user data, including student details, course progress, reviews, orders, subscriptions, etc. (Pro)<br />\nFix: Resolved the quiz waiting time issue for supported quiz types.<br />\nFix: Guest checkout now correctly registers students’ first and last names. (Pro)<br />\nFix: Importing courses now properly includes scheduled courses and assignment counts. (Pro)<br />\nFix: Resolved the dashboard slug issue when using the WPML plugin. (Pro)</p>\n<p>= 3.8.0 &#8211; Sep 04, 2025</p>\n<p>New: Gift Course – Users can now send courses as gifts to others. (Pro)<br />\nNew: Improved WP Admin menu organization for easier navigation.<br />\nNew: Manual enrollment support for subscription courses and course bundles. (Pro)<br />\nUpdate: Assignment filter now accurately filters data by selected start and end dates. (Pro)<br />\nUpdate: Enhanced Content Bank experience for instructors. (Pro)<br />\nUpdate: Improved quiz explanation.<br />\nUpdate: Added option to enable or disable course and bundle subscription plans. (Pro)<br />\nUpdate: Optimized the PDF certificate download process. (Pro)<br />\nFix: Paid courses could be mistakenly set as public.<br />\nFix: Incorrect tax was calculated during manual enrollment. (Pro)<br />\nFix: Topic count did not display on the backend courses page when no content was added.<br />\nFix: Students were able to access courses even after a custom extension date had expired. (Pro)<br />\nFix: Preferred course filter did not appear when the course filter was enabled.<br />\nFix: Lesson Preview was turning off after editing with the WordPress editor. (Pro)</p>\n<p>= 3.7.4 &#8211; Aug 22, 2025</p>\n<p>Fix: Resolved design issues when using RTL site languages</p>\n<p>= 3.7.3 &#8211; Aug 20, 2025</p>\n<p>Update: Improved WPML compatibility (Pro)<br />\nFix: Corrected an issue where public courses could be incorrectly set as paid<br />\nFix: Users with the Editor role were unable to view post previews<br />\nFix: The quiz timer paused when users were inactive or switched tabs<br />\nFix: Quiz submissions were possible even after the timer expired<br />\nFix: The calendar displayed incorrect dates when accessed from different time zones (Pro)<br />\nFix: Future-dated meetings and assignments were not rendered on the calendar (Pro)<br />\nFix: Users were unable to access bundle-based subscriptions (Pro)<br />\nFix: Entries were missing in the WooCommerce purchase history CSV</p>\n<p>= 3.7.2 &#8211; Aug 11, 2025</p>\n<p>Update: Added guest checkout support for Tutor Themes when using WooCommerce monetization.<br />\nUpdate: Added guest checkout support for Tutor Themes when using Native monetization. (Pro)<br />\nFix: Resolved course cart issues in Tutor Themes with WooCommerce monetization.<br />\nFix: Fixed a PHP error in the manual email editor. (Pro)</p>\n<p>= 3.7.1 &#8211; Aug 05, 2025</p>\n<p>Update: Seamlessly import existing course contents into the Content Bank (Pro).<br />\nUpdate: Cancelled subscriptions will now remain active until the end of their billing cycle (Pro).<br />\nUpdate: Admins can now add or remove courses from a course bundle at any time (Pro).<br />\nUpdate: Prerequisite rules now apply within a bundle if the required course is included (Pro).<br />\nUpdate: Enhanced compatibility with WPML for improved multilingual support (Pro).<br />\nUpdate: Various security enhancements implemented for better data protection.<br />\nUpdate: Improved course content sorting performance in the course builder.<br />\nFix: Unpublished ratings were incorrectly shown on instructor profiles.<br />\nFix: Improved LaTeX compatibility for lessons and assignments.<br />\nFix: Addressed a fatal error that occurred during student registration.<br />\nFix: Embedded videos can now be successfully added via the lesson REST API.<br />\nFix: Open-ended and short answer questions were missing from export files (Pro).<br />\nFix: Course builder now supports decimal values in course pricing.</p>\n<p>= 3.7.0 &#8211; Jul 22, 2025</p>\n<p>New: Content Bank — store and reuse lessons, questions, and assignments across multiple courses. (Pro)<br />\nNew: Option to customize certificate paper size. (Pro)<br />\nNew: New email trigger added for post-review submissions. (Pro)<br />\nNew: Added tax collection control for both individual courses and subscription plans. (Pro)<br />\nUpdate: Unified design system applied to listing and filtering components on Admin pages.<br />\nUpdate: Full user name now appears in password reset emails instead of the username/login.<br />\nFix: PHP fatal error when creating an assignment without a time limit in non-English languages. (Pro)<br />\nFix: MCQ question edits weren’t saving properly and showed outdated data.<br />\nFix: Import failed when file size exceeded the server&#8217;s maximum upload limit. (Pro)<br />\nFix: {instructor_feedback} placeholder wasn’t rendering after quiz feedback submission.<br />\nFix: Payments using Taiwan Dollar were failing due to a currency exchange error</p>\n<p><a href=\"https://tutorlms.com/releases/\" rel=\"nofollow ugc\">View the full changelog</a></p>\n\";s:11:\"screenshots\";s:8027:\"<ol><li><a href=\"https://ps.w.org/tutor/assets/screenshot-1.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-1.png?rev=3610477\" alt=\"Student Learning Area: Centralized learning experience with progress tracking and smooth navigation.\"></a><p>Student Learning Area: Centralized learning experience with progress tracking and smooth navigation.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-2.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-2.png?rev=3610477\" alt=\"App-like Experience: Smooth and responsive mobile interface with fast, touch-friendly interactions.\"></a><p>App-like Experience: Smooth and responsive mobile interface with fast, touch-friendly interactions.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-3.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-3.png?rev=3610477\" alt=\"Student Dashboard: Central hub for courses, progress, achievements, and recent activities.\"></a><p>Student Dashboard: Central hub for courses, progress, achievements, and recent activities.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-4.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-4.png?rev=3610477\" alt=\"Course Builder: Create your online courses fast with a more organized and intuitive workflow.\"></a><p>Course Builder: Create your online courses fast with a more organized and intuitive workflow.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-5.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-5.png?rev=3610477\" alt=\"Course Curriculum: Structure lessons, topics, quizzes, and assignments with visual organization.\"></a><p>Course Curriculum: Structure lessons, topics, quizzes, and assignments with visual organization.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-6.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-6.png?rev=3610477\" alt=\"Quiz Builder: Build interactive quizzes with 13 basic and advanced quiz types.\"></a><p>Quiz Builder: Build interactive quizzes with 13 basic and advanced quiz types.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-7.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-7.png?rev=3610477\" alt=\"Interactive Quiz Types: Multiple question formats for engaging and effective learner assessments.\"></a><p>Interactive Quiz Types: Multiple question formats for engaging and effective learner assessments.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-8.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-8.png?rev=3610477\" alt=\"Assignments: Manage submissions, reviews, grading, and learner feedback in one place.\"></a><p>Assignments: Manage submissions, reviews, grading, and learner feedback in one place.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-9.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-9.png?rev=3610477\" alt=\"Kids Mode: A playful learning interface specially designed for the younger learners.\"></a><p>Kids Mode: A playful learning interface specially designed for the younger learners.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-10.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-10.png?rev=3610477\" alt=\"AI Studio: Generate a full course with lessons, quizzes, assignments, etc using AI Studio.\"></a><p>AI Studio: Generate a full course with lessons, quizzes, assignments, etc using AI Studio.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-11.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-11.png?rev=3610477\" alt=\"Course List Page: Browse, filter, and discover courses through an improved catalog layout.\"></a><p>Course List Page: Browse, filter, and discover courses through an improved catalog layout.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-12.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-12.png?rev=3610477\" alt=\"Single Course Page: Showcase course details with a modern and learner-focused design.\"></a><p>Single Course Page: Showcase course details with a modern and learner-focused design.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-13.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-13.png?rev=3610477\" alt=\"Lesson Notes: Save personal notes from lessons and videos for quick future reference.\"></a><p>Lesson Notes: Save personal notes from lessons and videos for quick future reference.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-14.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-14.png?rev=3610477\" alt=\"Course Calendar: Track schedules, deadlines, and upcoming learning activities with ease.\"></a><p>Course Calendar: Track schedules, deadlines, and upcoming learning activities with ease.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-15.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-15.png?rev=3610477\" alt=\"Certificate Builder: Design customized course completion certificates with a visual editor.\"></a><p>Certificate Builder: Design customized course completion certificates with a visual editor.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-16.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-16.png?rev=3610477\" alt=\"Course Analytics: Monitor learner progress with clear reports and performance insights.\"></a><p>Course Analytics: Monitor learner progress with clear reports and performance insights.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-17.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-17.png?rev=3610477\" alt=\"Unified Discussions &amp; Q&amp;A: Manage learner discussions and questions from a single interface.\"></a><p>Unified Discussions &amp; Q&amp;A: Manage learner discussions and questions from a single interface.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-18.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-18.png?rev=3610477\" alt=\"Native eCommerce: Sell courses directly without any third-party eCommerce plugins.\"></a><p>Native eCommerce: Sell courses directly without any third-party eCommerce plugins.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-19.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-19.png?rev=3610477\" alt=\"Subscriptions and Memberships: Offer recurring plans and flexible access plans to course content.\"></a><p>Subscriptions and Memberships: Offer recurring plans and flexible access plans to course content.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-20.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-20.png?rev=3610477\" alt=\"Content Bank: Store and reuse lessons, quizzes, assignments, etc across multiple courses.\"></a><p>Content Bank: Store and reuse lessons, quizzes, assignments, etc across multiple courses.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-21.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-21.png?rev=3610477\" alt=\"Email Templates: Customize automated emails for learners, instructors, and administrators.\"></a><p>Email Templates: Customize automated emails for learners, instructors, and administrators.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-22.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-22.png?rev=3610477\" alt=\"Themes: Personalize your learning platform with professionally designed Tutor LMS themes.\"></a><p>Themes: Personalize your learning platform with professionally designed Tutor LMS themes.</p></li><li><a href=\"https://ps.w.org/tutor/assets/screenshot-23.png?rev=3610477\"><img src=\"https://ps.w.org/tutor/assets/screenshot-23.png?rev=3610477\" alt=\"Accessibility: Improve learning experience with built-in accessibility enhancements for all learners.\"></a><p>Accessibility: Improve learning experience with built-in accessibility enhancements for all learners.</p></li></ol>\";s:7:\"reviews\";s:26465:\"<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">A production LMS that failed at payments, grading, and notifications</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"1 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"1\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/dfcacad/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/80dd5b7a2374c373a877e34804ab764fce58b4583e21c13f3e9b74e38760ac6c?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/80dd5b7a2374c373a877e34804ab764fce58b4583e21c13f3e9b74e38760ac6c?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/dfcacad/\" class=\"reviewer-name\">dfcacad</a> el <span class=\"review-date\">septiembre 1, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>purchased Tutor LMS Pro to run a real, paid online academy. I am leaving this review after giving support repeated opportunities to investigate serious defects. Unfortunately, I have now reached the point where I cannot trust the platform with payments, student grades, or instructor notifications.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The problems are not minor cosmetic issues.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>1. Tutor LMS Native PayPal payments were approved but never captured</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I configured the Native PayPal integration using the information and webhook URL provided by Tutor LMS.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A customer attempted to purchase a subscription repeatedly. PayPal Merchant Technical Support investigated the affected orders and confirmed in writing that:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>The orders were created correctly.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The buyer approved the payments.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The card issuer authorised them.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>My merchant account was not restricted.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tutor LMS never sent the required Capture API request.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>I then checked PayPal’s webhook records myself. PayPal successfully sent <code>CHECKOUT.ORDER.APPROVED</code> to the exact webhook endpoint supplied by Tutor LMS, but the Tutor LMS endpoint returned:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><strong>HTTP 500 — Internal Server Error</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>Because Tutor LMS failed to process the approval webhook, the payments were never captured. The customer saw the temporary authorisations disappear and believed the payments had been rejected or refunded. No money was collected, and I lost the customer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This is a failure of a core commercial feature, not an inconvenience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>2. Quiz grading can begin at -1</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I have also encountered a quiz pass/fail calculation that starts at <strong>-1 instead of 0</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This reduces the grade a student can attain and can make the configured passing threshold unreachable. A student may therefore answer sufficiently well—or potentially answer everything correctly—and still be unable to reach the required passing grade.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>An LMS cannot be trusted when its grading logic may incorrectly prevent students from passing.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>3. Instructor quiz-submission emails are not sent</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Students submitted quizzes that required manual review, but I received no instructor email notifications.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>My WordPress site sends test emails, contact-form emails, and normal WordPress account emails successfully through the same SMTP server. Tutor LMS emails are the ones that fail.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Support installed an email-log plugin, and its own screenshot showed red failure icons beside every visible Tutor LMS email. The only successful message shown was a normal WordPress “New User” email.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Despite this, the agent repeatedly claimed the Tutor LMS messages were “sent correctly” and blamed my SMTP configuration without providing an SMTP response, PHP error, PHPMailer exception, or any other technical evidence.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>4. Support made unauthorized changes to my live website</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>During the investigation, the support agent:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Initially tested an unrelated dashboard announcement instead of the email issue I reported.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Disabled my caching plugin without asking permission.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Failed to restore it afterward.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Installed an additional email-log plugin without authorization.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Used a screenshot showing failed messages as supposed proof that the messages had been sent successfully.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Repeatedly stated conclusions that contradicted the evidence visible in that same screenshot.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Administrator access to a production website is not blanket permission to install plugins or alter its configuration without informing the owner.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I now have a platform where:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Customers can approve payments that are never collected.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Quiz grades may begin below zero.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Instructors may not be notified when quizzes require review.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Support makes unapproved changes while failing to identify the underlying errors.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>A learning management system has three fundamental responsibilities: <strong>collect payments, grade students accurately, and notify staff when action is required</strong>. In my experience, Tutor LMS has failed at all three.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>These failures have already caused direct business loss, and I cannot recommend Tutor LMS for production use in its current state.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>One star only because zero stars is not an option.</strong></p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Great support, but troubleshooting took a while</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/richard0508/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/104f98ec78288e14c888065567c94980e022d09e25ef99d7cbb0be0825f9ea5c?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/104f98ec78288e14c888065567c94980e022d09e25ef99d7cbb0be0825f9ea5c?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/richard0508/\" class=\"reviewer-name\">richard0508</a> el <span class=\"review-date\">agosto 19, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p><strong>Overall Experience:</strong> The support team is very helpful and eventually solved my issue.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Troubleshooting Process:</strong> It took quite a long time between replies, and I had to provide administrative access for them to identify that it was a plugin compatibility conflict.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Feedback:</strong> While the resolution was successful and the service itself is great, the process was a bit tedious and could be more efficient.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Great Support</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/mccartyconsulting/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/f54302a12a1ad3397985f1a08fe5a8be3f141c5684becf2e6fe2e4bfa678a459?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/f54302a12a1ad3397985f1a08fe5a8be3f141c5684becf2e6fe2e4bfa678a459?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/mccartyconsulting/\" class=\"reviewer-name\">mccartyconsulting</a> el <span class=\"review-date\">agosto 14, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>I has having an issue with student login working. Srijoni was assigned to my ticket and went above and beyond to assist me. Srijoni was patient, answered all my questions, and most importantly resolved the issue. Srijoni even provided advice on things to keep an eye on moving forward. I am very thankful for Srijoni‘s support. </p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">The Balanced Tech Reality</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"3 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"3\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/syxguns/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/e99506b8bd983b7248745f05a98c391cd0c380b3889c9adca1fb347a9ccbb04b?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/e99506b8bd983b7248745f05a98c391cd0c380b3889c9adca1fb347a9ccbb04b?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/syxguns/\" class=\"reviewer-name\">Syxguns</a> el <span class=\"review-date\">julio 30, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p><em>Tutor LMS Review: Great Turnkey LMS Product, Hostile Developer Experience</em>!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>The Bottom Line Score</strong><br />• Out-of-the-Box Buyer Rating: 7–8 / 10<br />• Developer Customization Rating: 4–5 / 10<br />• Honest Blended Score: ~5.5 / 10<br /><br />The Verdict in One Sentence: Treat Tutor LMS like Shopify bolted onto WordPress—it has a strong product surface out of the box, but a weak theming contract if you try to make it seamlessly match your custom brand.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>The Good: Why It Isn’t Lower</strong><br />Real Feature Depth: From lesson structures and quizzes to built-in e-commerce, certificate builders, and student dashboards, the core LMS functionality is solid and production-ready.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The \"App\" Trade-off: For site owners who just want to ship a functional school UI without fighting standard WP page templates, the isolated app model is a deliberate (and working) product choice.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Value &amp; Utility: If you hold a lifetime license, the working student flows and feature set still beat trying to build or rewrite a custom LMS from scratch.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>The Friction: Why It Isn’t Higher</strong><br />Not a True \"Theme Citizen\": It acts like an application bolted onto WordPress rather than native software. The dashboard builds its own HTML shell, meaning your theme\'s native headers and footers aren\'t treated as first-class elements.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Hostile CSS Architecture: Theming feels like fighting a system built with nested CSS variable token trees, utility class soup, and hardcoded inline styles. Overriding simple background colors or modal headers quickly turns into an !important treadmill.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Integration &amp; Security Friction: Common integration snags (like back_url redirects triggering security plugins, double-slash asset paths tutor//assets, or JSON endpoints getting flagged by plugin firewalls) often manifest as \"your fault\" support tickets.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Superficial Hook System: PHP hooks help around the edges for basic data filters, but they won\'t save you for core layout or deep brand control once the underlying frontend architecture has already made up its mind.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Closing Thoughts &amp; Final Advice</strong><br />I own the Pro version of this software, and overall, I couldn\'t be happier with what it accomplishes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I did spend some time dealing with a couple of redirect issues in my security plugin. I also fought tooth and nail against the CSS trying to get it to blend seamlessly as part of my custom theme. I found the process so frustrating that I eventually decided to stop making changes—I\'m not 100% happy with my styling tweaks, but I simply no longer wanted to fight the system.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>As a standalone platform integrated into your site, it is fantastic. Just don\'t fight with it the way I tried to. There simply isn\'t enough time in the day to wrestle with its CSS, so my best advice is to embrace and love what Tutor LMS 4 has to offer out of the box!</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">A powerful LMS with responsive support</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/etre1/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/ce966dd9111f5046ce8adc15c457d969f805de59c05101f56ea5220baab61b8f?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/ce966dd9111f5046ce8adc15c457d969f805de59c05101f56ea5220baab61b8f?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/etre1/\" class=\"reviewer-name\">etre1</a> el <span class=\"review-date\">julio 29, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Tutor LMS Pro is a feature-rich platform that covers everything I need to run an e-learning site with subscriptions, drip content, quizzes, and certificates. The interface is intuitive and the plugin integrates well with the WordPress ecosystem.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I won\'t hide that I encountered several difficulties along the way, both before and after the migration to version 4.0, which came with some breaking changes. However, the support team has always been responsive and genuinely helpful in resolving issues.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Horrible experiencia en la actualización</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"1 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"1\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/guezs/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/bd9d2325d4bb45a4ddba0dd32ac429062c5ac8afe0573f6b63cb8e2d2d35ee83?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/bd9d2325d4bb45a4ddba0dd32ac429062c5ac8afe0573f6b63cb8e2d2d35ee83?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/guezs/\" class=\"reviewer-name\">guezs</a> el <span class=\"review-date\">julio 20, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Ha cambiado todo. Los menús están en inglés. Las personalizaciones no funcionan. Los usuarios están desconcertados y perdidos.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Auto-update to 4.0 and closed support threads?</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"2 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"2\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/lazarmld/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/dc3354011a571e355b78ea5d26100c7d0e82f71761c9b733e37c996e4df09ad2?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/dc3354011a571e355b78ea5d26100c7d0e82f71761c9b733e37c996e4df09ad2?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/lazarmld/\" class=\"reviewer-name\">lazarmld</a> el <span class=\"review-date\">julio 10, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>It\'s great plugin and all, but this auto-update to 4.0 version and breaking everyones sites is a bold move. <br />And then closing option to open a ticket for a free plugin is even bolder. <br /><br />Well played Tutor.<br /><br />Edit: they have open the support threads, you get one star back<br /></p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Support team is very helpful</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/susanbastin/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/4df32f321b3ecd29dbf67510be308c8341a1a8859e4095122008a625101569ea?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/4df32f321b3ecd29dbf67510be308c8341a1a8859e4095122008a625101569ea?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/susanbastin/\" class=\"reviewer-name\">susanbastin</a> el <span class=\"review-date\">abril 27, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Support team is very helpful, especially Mr. Rashed helped me a lot.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Bad Support</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"2 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"2\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/lashram/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/15d8fccf74db57761089e28510d45775fad0d8a1847b2d594b86f795c123c877?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/15d8fccf74db57761089e28510d45775fad0d8a1847b2d594b86f795c123c877?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/lashram/\" class=\"reviewer-name\">lashram</a> el <span class=\"review-date\">abril 4, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Having issues with TutorLMS on my site and the 24/7 support isn\'t live, I wanted to work through my issues in real time and their only offer was for me to provide access to my admin.  Absolutely not!  I don\'t trust anyone with admin access unsupervised!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Luckily it\'s opensource and I have some skills ...  </p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Great support in onboarding</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 de 5 estrellas\" data-title-template=\"%s de 5 estrellas\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				Por <a href=\"https://profiles.wordpress.org/karanu123/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/5f168f520cd10545514572452b75fb578c507f0058a1379089eaa0b17e202e29?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/5f168f520cd10545514572452b75fb578c507f0058a1379089eaa0b17e202e29?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/karanu123/\" class=\"reviewer-name\">karanu123</a> el <span class=\"review-date\">febrero 11, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>I bought the Tutor Pro app, but had challenges installing the theme. I applaud the support team for guiding me through the entire onboarding process and forsetting up the app and theme on my site. All I have to do is create my courses and edit the theme to my liking. Thank you, the support team. </p>\n<!-- /wp:paragraph --></div>\n</div>\n\";}s:17:\"short_description\";s:71:\"A complete WordPress LMS plugin to create any eLearning website easily.\";s:13:\"download_link\";s:54:\"https://downloads.wordpress.org/plugin/tutor.4.0.7.zip\";s:14:\"upgrade_notice\";a:1:{s:0:\"\";s:92:\"<p>It’s recommended to have a backup of your website before hitting the update button.</p>\";}s:11:\"screenshots\";a:23:{i:1;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-1.png?rev=3610477\";s:7:\"caption\";s:100:\"Student Learning Area: Centralized learning experience with progress tracking and smooth navigation.\";}i:2;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-2.png?rev=3610477\";s:7:\"caption\";s:99:\"App-like Experience: Smooth and responsive mobile interface with fast, touch-friendly interactions.\";}i:3;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-3.png?rev=3610477\";s:7:\"caption\";s:90:\"Student Dashboard: Central hub for courses, progress, achievements, and recent activities.\";}i:4;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-4.png?rev=3610477\";s:7:\"caption\";s:93:\"Course Builder: Create your online courses fast with a more organized and intuitive workflow.\";}i:5;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-5.png?rev=3610477\";s:7:\"caption\";s:96:\"Course Curriculum: Structure lessons, topics, quizzes, and assignments with visual organization.\";}i:6;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-6.png?rev=3610477\";s:7:\"caption\";s:78:\"Quiz Builder: Build interactive quizzes with 13 basic and advanced quiz types.\";}i:7;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-7.png?rev=3610477\";s:7:\"caption\";s:97:\"Interactive Quiz Types: Multiple question formats for engaging and effective learner assessments.\";}i:8;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-8.png?rev=3610477\";s:7:\"caption\";s:85:\"Assignments: Manage submissions, reviews, grading, and learner feedback in one place.\";}i:9;a:2:{s:3:\"src\";s:58:\"https://ps.w.org/tutor/assets/screenshot-9.png?rev=3610477\";s:7:\"caption\";s:84:\"Kids Mode: A playful learning interface specially designed for the younger learners.\";}i:10;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-10.png?rev=3610477\";s:7:\"caption\";s:90:\"AI Studio: Generate a full course with lessons, quizzes, assignments, etc using AI Studio.\";}i:11;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-11.png?rev=3610477\";s:7:\"caption\";s:90:\"Course List Page: Browse, filter, and discover courses through an improved catalog layout.\";}i:12;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-12.png?rev=3610477\";s:7:\"caption\";s:85:\"Single Course Page: Showcase course details with a modern and learner-focused design.\";}i:13;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-13.png?rev=3610477\";s:7:\"caption\";s:85:\"Lesson Notes: Save personal notes from lessons and videos for quick future reference.\";}i:14;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-14.png?rev=3610477\";s:7:\"caption\";s:88:\"Course Calendar: Track schedules, deadlines, and upcoming learning activities with ease.\";}i:15;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-15.png?rev=3610477\";s:7:\"caption\";s:91:\"Certificate Builder: Design customized course completion certificates with a visual editor.\";}i:16;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-16.png?rev=3610477\";s:7:\"caption\";s:87:\"Course Analytics: Monitor learner progress with clear reports and performance insights.\";}i:17;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-17.png?rev=3610477\";s:7:\"caption\";s:100:\"Unified Discussions &amp; Q&amp;A: Manage learner discussions and questions from a single interface.\";}i:18;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-18.png?rev=3610477\";s:7:\"caption\";s:82:\"Native eCommerce: Sell courses directly without any third-party eCommerce plugins.\";}i:19;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-19.png?rev=3610477\";s:7:\"caption\";s:97:\"Subscriptions and Memberships: Offer recurring plans and flexible access plans to course content.\";}i:20;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-20.png?rev=3610477\";s:7:\"caption\";s:89:\"Content Bank: Store and reuse lessons, quizzes, assignments, etc across multiple courses.\";}i:21;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-21.png?rev=3610477\";s:7:\"caption\";s:90:\"Email Templates: Customize automated emails for learners, instructors, and administrators.\";}i:22;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-22.png?rev=3610477\";s:7:\"caption\";s:89:\"Themes: Personalize your learning platform with professionally designed Tutor LMS themes.\";}i:23;a:2:{s:3:\"src\";s:59:\"https://ps.w.org/tutor/assets/screenshot-23.png?rev=3610477\";s:7:\"caption\";s:101:\"Accessibility: Improve learning experience with built-in accessibility enhancements for all learners.\";}}s:4:\"tags\";a:5:{s:6:\"course\";s:6:\"course\";s:9:\"education\";s:9:\"education\";s:9:\"elearning\";s:9:\"elearning\";s:26:\"learning-management-system\";s:26:\"learning management system\";s:3:\"lms\";s:3:\"lms\";}s:8:\"versions\";a:191:{s:5:\"1.0.0\";s:54:\"https://downloads.wordpress.org/plugin/tutor.1.0.0.zip\";s:11:\"1.0.0-alpha\";s:60:\"https://downloads.wordpress.org/plugin/tutor.1.0.0-alpha.zip\";s:5:\"1.0